def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    hat_patches = image_patch.find("hat")
    dance_patches = image_patch.find("dancing")

    if not man_patches or not hat_patches or not dance_patches:
        return image_patch

    man_hat_pairs = []
    for man in man_patches:
        for hat in hat_patches:
            if man.overlaps_with(hat.left, hat.lower, hat.right, hat.upper):
                man_hat_pairs.append((man, hat))

    dancing_man_hat_pairs = []
    for man_hat_pair in man_hat_pairs:
        man, hat = man_hat_pair
        for dance in dance_patches:
            if man.overlaps_with(dance.left, dance.lower, dance.right, dance.upper):
                dancing_man_hat_pairs.append(man_hat_pair)

    if not dancing_man_hat_pairs:
        return image_patch

    return dancing_man_hat_pairs[0][0]

